/// <summary>
/// MPJ_22903_SalesOrderGuide
/// Handles execution of sales order guides (applying checks and updates to orders
/// based on applicable guide).
/// </summary>
class METSalesOrderGuideExecution
{
    // Params
    SalesId                     salesID;

    // State
    METCustParameters           metCustParams;
    SalesTable                  salesTable;
    METCustTable                metCustTable; 
    CustTable                   custTable;

}

Method.Source:
    /// <summary>
    /// run
    /// </summary>
    public void run()
    {
        SalesUpdateRemain salesUpdateRemain;

        metCustParams = METCustParameters::Find();
        
        setPrefix("@MET:SalesOrderGuideProcessInfoLogPrefix");

        salesTable = SalesTable::find(salesId);
        if(!salesTable)
        {
            throw error(strFmt("@MET:SalesOrderNotFound", salesId));
        }

        SalesLine       salesLine;
        METSalesLine    metSalesLine;

        metCustTable    = METCustTable::find(salesTable.CustAccount);        
        custTable       = salesTable.custTable_CustAccount();

        ttsbegin;

        while select forupdate salesLine
            where   salesLine.SalesId       == salesTable.SalesId
        join forupdate metSalesLine
            where   metSalesLine.SalesLine  == salesLine.RecId
        {
            if(!METSalesOrderGuideExecution::isItemOrderable(salesLine.CustAccount, salesLine.ItemId))
            {
                salesUpdateRemain = SalesUpdateRemain::construct();
                salesUpdateRemain.updateDeliverRemainder(salesLine, 0, 0);

                if(metCustParams.OrderGuideNotInRangeReasonId)
                {
                    salesLine.reread();
                    metSalesLine.reread();
                    metSalesLine.ReasonID = metCustParams.OrderGuideNotInRangeReasonId;
                    salesLine.metPackMETSalesLine(metSalesLine);
                    salesLine.update();
                }                
                warning(strFmt("@MET:SalesOrderGuideLineCancelledMessage", salesLine.ItemId));
            }
        }
        ttscommit;        
    }

    /// <summary>
    /// Check if an item is orderable based on matching order guide entries.
    /// </summary>
    /// <param name = "_custAccount">customer account number</param>
    /// <param name = "_itemId">item number</param>
    /// <returns>True if the item is orderable for a specified customer, else false</returns>
    static public boolean isItemOrderable(CustAccount _custAccount, ItemId _itemId)
    {
        boolean                 inclusionFound, exclusionFound;
        METSalesOrderGuideItem  sellListAnyReference, guideItem;

        CustTable               custTable       = CustTable::find(_custAccount);
        METCustTable            metCustTable    = METCustTable::find(custTable.AccountNum);

        select firstonly RecId from sellListAnyReference
            where   sellListAnyReference.ItemId    == _itemId
            &&      sellListAnyReference.LineType  == METSalesOrderGuideInclusion::Include;

        while select LineType from guideItem
            where   guideItem.ItemId            == _itemId
            && (
                       (guideItem.ReferenceType == METSalesOrderGuideReferenceType::Customer                    && guideItem.Reference == custTable.AccountNum)
                    || (guideItem.ReferenceType == METSalesOrderGuideReferenceType::CustomerOperationsGroup     && guideItem.Reference == metCustTable.CustOperGroupId)
                    || (guideItem.ReferenceType == METSalesOrderGuideReferenceType::Site                        && guideItem.Reference == custTable.InventSiteId)
                    || (guideItem.ReferenceType == METSalesOrderGuideReferenceType::State                       && guideItem.Reference == custTable.mcrDefaultDeliveryPostalAddress().State)
            )
        {
            switch(guideItem.LineType)
            {
                case METSalesOrderGuideInclusion::Include:
                    inclusionFound = true;
                    break;
                case METSalesOrderGuideInclusion::Exclude:
                    exclusionFound = true;
                    break;
            }
        }

        if(sellListAnyReference)
        {
            // Sell to to list for item is not empty
            if(inclusionFound)
            {
                // Inclusion found
                if(exclusionFound)
                {
                    // Inclusion found, but exclusion also found
                    return false;
                }
                else
                {
                    // Inclusion found, and no exclusion found
                    return true;
                }
            }
            else
            {
                // Item referenced in sell to list, but no specific inclusion for this account/ref found
                return false;
            }
        }
        else
        {
            // Item not referenced in sell-to list
            if(exclusionFound)
            {
                // Item not referenced in sell list, but found in do-not-sell list
                return false;
            }
            else
            {
                // Item not referenced in sell list, and not found in do-not-sell list
                return true;
            }
        }
    }

/// <summary>
/// Get/set sales ID
/// </summary>
/// <param name = "_salesID">_salesID</param>
/// <returns>salesID</returns>
public SalesID parmSalesID(SalesId _salesID = salesID)
{
    salesID = _salesID;
    return salesID;
}

/// <summary>
/// Apply order guide checks to specified order.
/// </summary>
/// <param name = "_salesID">Sales order</param>
public static void applyChecksToOrder(SalesId _salesID)
{
    METSalesOrderGuideExecution exec = new METSalesOrderGuideExecution();
    exec.parmSalesID(_salesID);
    exec.run();
}
